function measureText(a, b) { const d = Math.hypot(a.pts[0][0] - b.pts[0][0], a.pts[0][1] - b.pts[0][1]); const via = places().find((p) => p.k === 'line' && p.role === 'road' && (a.ent === 'Customs house' || b.ent === 'Customs house')); const len = via ? via.pts.slice(1).reduce((s, p, i) => s + Math.hypot(p[0] - via.pts[i][0], p[1] - via.pts[i][1]), 0) : null; return `${esc(a.ent)} to ${esc(b.ent)}: <b>${fx(d)} ${esc(curMap().unit)}</b> in a straight line.${len ? ` By connections: ${esc(via.ent)}, ${Math.round(len)} ${esc(curMap().unit)}.` : ' By connections: unknown. No connection with a length joins them.'}`; }
